SET local check_function_bodies = off;

CREATE SCHEMA "private";

CREATE TABLE "private"."gabaritos" (
  "questao_id"       bigint NOT NULL,
  "resposta_correta" text   NOT NULL,
  CONSTRAINT "gabaritos_pkey" PRIMARY KEY (questao_id),
  CONSTRAINT "gabaritos_resposta_correta_check" CHECK ((resposta_correta = ANY (ARRAY['A'::text, 'B'::text, 'C'::text, 'D'::text])))
);

ALTER TABLE "private"."gabaritos"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."atividades" (
  "id"        bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "titulo"    text                     NOT NULL,
  "descricao" text,
  "nivel"     text                     NOT NULL,
  "ativo"     boolean                  NOT NULL DEFAULT true,
  "criado_em" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "atividades_nivel_check" CHECK ((nivel = ANY (ARRAY['facil'::text, 'medio'::text, 'avancado'::text]))),
  CONSTRAINT "atividades_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."atividades"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."modulos" (
  "id"        bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "nome"      text                     NOT NULL,
  "descricao" text,
  "ordem"     integer                  NOT NULL DEFAULT 0,
  "ativo"     boolean                  NOT NULL DEFAULT true,
  "criado_em" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "modulos_nome_key" UNIQUE (nome),
  CONSTRAINT "modulos_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."modulos"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."palavras" (
  "id"                 bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "modulo_id"          bigint                   NOT NULL,
  "termo_kambeba"      text                     NOT NULL,
  "traducao_portugues" text                     NOT NULL,
  "audio_url"          text,
  "ativo"              boolean                  NOT NULL DEFAULT true,
  "criado_em"          timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "palavras_modulo_termo_unique" UNIQUE (modulo_id, termo_kambeba),
  CONSTRAINT "palavras_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."palavras"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."questoes" (
  "id"           bigint  GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "atividade_id" bigint  NOT NULL,
  "enunciado"    text    NOT NULL,
  "alternativas" jsonb   NOT NULL,
  "ordem"        integer NOT NULL DEFAULT 0,
  "ativo"        boolean NOT NULL DEFAULT true,
  CONSTRAINT "questoes_alternativas_check" CHECK (((jsonb_typeof(alternativas) = 'object'::text) AND (alternativas ?& ARRAY['A'::text, 'B'::text, 'C'::text, 'D'::text]))),
  CONSTRAINT "questoes_atividade_id_ordem_key" UNIQUE (atividade_id, ordem),
  CONSTRAINT "questoes_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."questoes"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."resultados" (
  "id"              bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "usuario_id"      uuid                     NOT NULL,
  "atividade_id"    bigint                   NOT NULL,
  "acertos"         integer                  NOT NULL,
  "total_questoes"  integer                  NOT NULL,
  "data_realizacao" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "resultados_acertos_check" CHECK ((acertos >= 0)),
  CONSTRAINT "resultados_check" CHECK ((acertos <= total_questoes)),
  CONSTRAINT "resultados_pkey" PRIMARY KEY (id),
  CONSTRAINT "resultados_total_questoes_check" CHECK ((total_questoes > 0))
);

ALTER TABLE "public"."resultados"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."usuarios" (
  "id"        uuid                     NOT NULL,
  "nome"      text,
  "criado_em" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "usuarios_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."usuarios"
  ENABLE ROW LEVEL SECURITY;

CREATE OR REPLACE FUNCTION public.handle_new_user()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
BEGIN
    INSERT INTO public.usuarios (id, nome)
    VALUES (
        NEW.id,
        COALESCE(
            NEW.raw_user_meta_data ->> 'nome',
            NEW.raw_user_meta_data ->> 'full_name'
        )
    )
    ON CONFLICT (id) DO NOTHING;

    RETURN NEW;
END;
$function$;

REVOKE ALL ON FUNCTION "public"."handle_new_user"() FROM PUBLIC, "anon", "authenticated";

ALTER TABLE "public"."palavras"
  ADD CONSTRAINT "palavras_modulo_id_fkey" FOREIGN KEY (modulo_id) REFERENCES public.modulos(id) ON DELETE RESTRICT;

ALTER TABLE "public"."questoes"
  ADD CONSTRAINT "questoes_atividade_id_fkey" FOREIGN KEY (atividade_id) REFERENCES public.atividades(id) ON DELETE CASCADE;

ALTER TABLE "private"."gabaritos"
  ADD CONSTRAINT "gabaritos_questao_id_fkey" FOREIGN KEY (questao_id) REFERENCES public.questoes(id) ON DELETE CASCADE;

ALTER TABLE "public"."resultados"
  ADD CONSTRAINT "resultados_atividade_id_fkey" FOREIGN KEY (atividade_id) REFERENCES public.atividades(id) ON DELETE RESTRICT;

ALTER TABLE "public"."usuarios"
  ADD CONSTRAINT "usuarios_id_fkey" FOREIGN KEY (id) REFERENCES auth.users(id) ON DELETE CASCADE;

ALTER TABLE "public"."resultados"
  ADD CONSTRAINT "resultados_usuario_id_fkey" FOREIGN KEY (usuario_id) REFERENCES public.usuarios(id) ON DELETE CASCADE;

CREATE INDEX idx_palavras_modulo ON public.palavras USING btree (modulo_id);

CREATE INDEX idx_questoes_atividade ON public.questoes USING btree (atividade_id);

CREATE INDEX idx_resultados_atividade ON public.resultados USING btree (atividade_id);

CREATE INDEX idx_resultados_usuario ON public.resultados USING btree (usuario_id);

CREATE TRIGGER on_auth_user_created
  AFTER INSERT ON auth.users
  FOR EACH ROW
  EXECUTE FUNCTION public.handle_new_user();

CREATE POLICY "atividades_ativas_leitura" ON "public"."atividades"
  FOR SELECT
  TO "anon", "authenticated"
  USING ((ativo = true));

CREATE POLICY "modulos_ativos_leitura" ON "public"."modulos"
  FOR SELECT
  TO "anon", "authenticated"
  USING ((ativo = true));

CREATE POLICY "palavras_ativas_leitura" ON "public"."palavras"
  FOR SELECT
  TO "anon", "authenticated"
  USING ((ativo = true));

CREATE POLICY "questoes_ativas_leitura" ON "public"."questoes"
  FOR SELECT
  TO "anon", "authenticated"
  USING (((ativo = true) AND (EXISTS ( SELECT 1
   FROM public.atividades a
  WHERE ((a.id = questoes.atividade_id) AND (a.ativo = true))))));

CREATE POLICY "usuario_le_proprios_resultados" ON "public"."resultados"
  FOR SELECT
  TO "authenticated"
  USING ((usuario_id = ( SELECT auth.uid() AS uid)));

CREATE POLICY "usuario_atualiza_proprio_perfil" ON "public"."usuarios"
  FOR UPDATE
  TO "authenticated"
  USING ((id = ( SELECT auth.uid() AS uid)))
  WITH CHECK ((id = ( SELECT auth.uid() AS uid)));

CREATE POLICY "usuario_insere_proprio_perfil" ON "public"."usuarios"
  FOR INSERT
  TO "authenticated"
  WITH CHECK ((id = ( SELECT auth.uid() AS uid)));

CREATE POLICY "usuario_le_proprio_perfil" ON "public"."usuarios"
  FOR SELECT
  TO "authenticated"
  USING ((id = ( SELECT auth.uid() AS uid)));

REVOKE ALL ON FUNCTION "public"."handle_new_user"() FROM "postgres";

GRANT EXECUTE ON FUNCTION "public"."handle_new_user"() TO "postgres";

GRANT EXECUTE ON FUNCTION "public"."handle_new_user"() TO "service_role";

